import zeros = require( '@stdlib/ndarray/zeros' );
import dnrm2 = require( './index' );


// TESTS //

// The function returns a number...
{
	dnrm2( zeros( [ 10 ] ) ); // $ExpectType float64ndarray
	dnrm2( zeros( [ 10 ] ), -1 ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	dnrm2( 10 ); // $ExpectError
	dnrm2( '10' ); // $ExpectError
	dnrm2( true ); // $ExpectError
	dnrm2( false ); // $ExpectError
	dnrm2( null ); // $ExpectError
	dnrm2( undefined ); // $ExpectError
	dnrm2( {} ); // $ExpectError
	dnrm2( [] ); // $ExpectError
	dnrm2( ( x: number ): number => x ); // $ExpectError

	dnrm2( 10, -1 ); // $ExpectError
	dnrm2( '10', -1 ); // $ExpectError
	dnrm2( true, -1 ); // $ExpectError
	dnrm2( false, -1 ); // $ExpectError
	dnrm2( null, -1 ); // $ExpectError
	dnrm2( undefined, -1 ); // $ExpectError
	dnrm2( {}, -1 ); // $ExpectError
	dnrm2( [], -1 ); // $ExpectError
	dnrm2( ( x: number ): number => x, -1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 10 ] );

	dnrm2( x, '10' ); // $ExpectError
	dnrm2( x, true ); // $ExpectError
	dnrm2( x, false ); // $ExpectError
	dnrm2( x, null ); // $ExpectError
	dnrm2( x, {} ); // $ExpectError
	dnrm2( x, [] ); // $ExpectError
	dnrm2( x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 10 ] );

	dnrm2(); // $ExpectError
	dnrm2( x, -1, {} ); // $ExpectError
}
